  input_tax: number;
  /** 上期累積留抵稅額 */
  carry_in: number;
  /** output_tax − input_tax − carry_in (negative = credit) */
  net_tax: number;
  /** 本期應實繳稅額 */
  payable: number;
  /** 本期申報留抵稅額 */
  carry_out: number;
